begin;
select set_config('request.jwt.claim.sub',(select user_id::text from public.app_members where active and role='admin' limit 1),true);
select set_config('request.jwt.claims',jsonb_build_object('amr',jsonb_build_array(jsonb_build_object('method','password','timestamp',extract(epoch from now()))))::text,true);
insert into public.products(id,sku,name,category,mode,owner_name,price,qty) values('qa-customer-product','QA-CUSTOMER','Produto','Perfumes','proprio','QA',100,20);
set local role authenticated;
do $$ declare cid uuid:=gen_random_uuid(); other uuid:=gen_random_uuid(); c jsonb; n bigint; d jsonb; rev jsonb; sale text; old_schedule jsonb; q uuid:=gen_random_uuid(); begin
 c:=public.customer_accounts('create',jsonb_build_object('request_id',cid,'name','Tatiana Silva','phone',''));n:=(c->>'customer_number')::bigint;
 assert public.customer_accounts('create',jsonb_build_object('request_id',cid,'name','Tatiana Silva','phone',''))->>'customer_number'=n::text,'Retry generated new number';
 begin perform public.customer_accounts('create',jsonb_build_object('request_id',other,'name','Tatiana Silva','phone',''));raise exception 'Duplicate accepted without confirmation';exception when sqlstate '22023' then null;end;
 c:=public.customer_accounts('create',jsonb_build_object('request_id',other,'name','Tatiana Silva','phone','','allow_duplicate',true));assert (c->>'customer_number')::bigint>n,'Number not increasing';
 begin perform public.customer_accounts('create',jsonb_build_object('request_id',gen_random_uuid(),'name','Tatiana','phone',''));raise exception 'Single name allowed';exception when sqlstate '22023' then null;end;
 d:=jsonb_build_object('customer_id',cid,'p_cart_id','qa-client-one','p_payment','Crediário VIP','p_items','[{"product_id":"qa-customer-product","qty":1}]'::jsonb,'p_plan',jsonb_build_object('down_payment',20,'down_payment_method','Pix','installments',jsonb_build_array(jsonb_build_object('amount',80,'due_date',current_date+30))),'p_discount_percent',0,'p_channel','Loja física','p_customer_type','novo','p_purchase_profile','uso_proprio');
 perform public.customer_accounts('checkout',d);perform public.customer_accounts('checkout',d);
 perform public.customer_accounts('checkout',d||'{"p_cart_id":"qa-client-two"}');
 assert (select count(*)=2 and bool_and(customer_id=cid) from public.sales where cart_id in ('qa-client-one','qa-client-two')),'Separate purchases not linked';
 assert (select qty=18 from public.products where id='qa-customer-product'),'Retry lowered stock';
 select jsonb_agg(to_jsonb(r) order by id) into old_schedule from public.receivable_installments r where cart_id in ('qa-client-one','qa-client-two');
 c:=public.customer_accounts('update',jsonb_build_object('request_id',q,'customer_id',cid,'revision',0,'name','Tatiana Souza','phone','86999999999','reason','Corrigir sobrenome'));
 assert (c->>'customer_number')::bigint=n,'Rename changed number';
 assert (select bool_and(customer_name='Tatiana Souza') from public.sales where customer_id=cid),'Rename not reflected';
 assert (select name='Tatiana Silva' from public.customers where id=other),'Namesakes merged';
 assert old_schedule=(select jsonb_agg(to_jsonb(r) order by id) from public.receivable_installments r where cart_id in ('qa-client-one','qa-client-two')),'Rename modified schedule';
 select min(id),jsonb_object_agg(id,revision) into sale,rev from public.sales where cart_id='qa-client-two';
 perform public.customer_accounts('assign',jsonb_build_object('request_id',gen_random_uuid(),'customer_id',other,'sale_id',sale,'revisions',rev,'reason','Compra pertence a outra pessoa'));
 assert (select customer_id=other from public.sales where id=sale),'Reassignment failed';
 assert (select sum(amount-paid_amount)=160 from public.receivable_installments where cart_id in ('qa-client-one','qa-client-two')),'Debt changed';
 assert (select sum(amount)=40 from public.receivable_payments where receivable_id in (select id from public.receivable_installments where cart_id in ('qa-client-one','qa-client-two'))),'Receipts changed';
 begin perform public.customer_accounts('checkout',d||jsonb_build_object('customer_id',other));raise exception 'Retry changed customer';exception when sqlstate '22023' then null;end;
 d:=d||jsonb_build_object('p_cart_id','qa-client-cash','p_payment','Dinheiro','p_installments',1,'p_receiving_plan','one_day','p_rate_tier','standard');
 perform public.customer_accounts('checkout',d);perform public.customer_accounts('checkout',d);
 assert (select count(*)=1 and bool_and(customer_id=cid) from public.sales where cart_id='qa-client-cash'),'Cash customer link or retry failed';
 perform public.customer_accounts('checkout',(d-'customer_id')||jsonb_build_object('p_cart_id','qa-cash-anonymous'));
 assert (select customer_id is null from public.sales where cart_id='qa-cash-anonymous'),'Optional customer failed';
 assert (select qty=16 from public.products where id='qa-customer-product'),'Cash stock mismatch';
end $$;
reset role;
set local role anon;
do $$ begin begin perform public.customer_accounts('create','{}');raise exception 'Anonymous access allowed';exception when insufficient_privilege then null;end;end $$;
reset role;
rollback;
select 'PASS: numbered customers, duplicate warning, namesake separation, required surname, multiple purchases, retry safety, permanent number after rename, reassignment and preserved financial data' as result;
